public boolean sourceTableSkipGUPCalculation(Common _source)
{
    SalesTable salesTable;
    METSalesTable metSalesTable;
    boolean ret = next sourceTableSkipGUPCalculation(_source);
    switch (_source.TableId)
    {
        case tableNum(SalesTable):
            salesTable = _source;
            metSalesTable = METSalesTable::findByRefRecId(salesTable.RecId);
            // Task192490_CB888_SalesOrderHeaderCharges
            METSalesOrderProcessingStatus salesOrderProcessingStatusPricing = SalesParameters::find().METSalesOrderProcessingStatus;
            if(metSalesTable.OrderProcessingStatus == salesOrderProcessingStatusPricing ||
               metSalesTable.OrderProcessingStatus == METSalesOrderProcessingStatus::OptimisationCompleted)
            {
                return false;
            }
            break;
    }
    return ret;
}
